INSERT OR IGNORE INTO reports (id,title,message,category,reporter_id,submitted_at,colony_id,cat_id,care_note,urgent,status) VALUES ('report-injury','Possible injury near the feeding station','Pepper was limping on his front paw this morning. He stayed by the fence and did not come over for food. I left water nearby. Can someone check on him?','Care concern','local-member','2026-11-07T10:40:00-05:00','riverside','pepper','Reported limping on a front paw and reduced interest in food. Needs a care check.',1,'pending');
INSERT OR IGNORE INTO reports (id,title,message,category,reporter_id,submitted_at,colony_id,cat_id,care_note,urgent,status) VALUES ('report-kittens','Three kittens spotted behind the shed','I saw three small kittens behind the shed at Canal. An adult cat was nearby. I kept my distance and left the area quiet. I do not know whether they are already in our records.','New sighting','local-member','2026-11-07T09:15:00-05:00','canal',NULL,'Three kittens reported behind the shed. Identity and age are unconfirmed.',1,'pending');
