INSERT OR IGNORE INTO community_posts (id, kind, title, description, area, schedule, published, position) VALUES ('morning-feeding', 'opening', 'Morning feeding volunteers', 'Help keep food and water bowls full on a regular care route. You’ll start alongside an experienced volunteer and get to know the cats together.', 'North service area', 'Weekday mornings · 1 hour a week', 1, 0);
INSERT OR IGNORE INTO community_posts (id, kind, title, description, area, schedule, published, position) VALUES ('clinic-transport', 'opening', 'Help cats get to the clinic', 'Drive cats to and from scheduled clinic visits. The care team coordinates each trip and provides carriers; you bring a reliable vehicle.', 'Across the neighborhood', 'Flexible weekdays · 2–3 hours a month', 1, 1);
INSERT OR IGNORE INTO community_posts (id, kind, title, description, area, schedule, published, position) VALUES ('supply-team', 'opening', 'Join the weekend supply team', 'Sort food donations and pack supplies for local care routes. This is a hands-on way to help, even if you’re new to community cat care.', 'Central service area', 'Saturday mornings · 2 hours a month', 1, 2);
INSERT OR IGNORE INTO community_posts (id, kind, title, description, published_date, published, position) VALUES ('winter-supply-drive', 'news', 'A little extra care for colder days', 'Our winter supply drive starts November 14. The team is gathering unopened cat food, clean feeding bowls, and straw for outdoor shelters. Volunteers will sort donations at the next supply morning.', '2026-11-06', 1, 0);
INSERT OR IGNORE INTO community_posts (id, kind, title, description, published_date, published, position) VALUES ('volunteer-welcome', 'news', 'Meet the team at our next volunteer welcome', 'Our next welcome session is November 12. Meet other volunteers, learn how care routes work, and find a role that fits your schedule. New helpers can join an experienced team member for their first visit.', '2026-11-04', 1, 1);
INSERT OR IGNORE INTO community_posts (id, kind, title, description, published_date, published, position) VALUES ('october-care', 'news', 'Small visits. A month of steady care.', 'In October, our volunteers completed 86 care visits across three service areas. Thank you to everyone who filled a bowl, shared an update, or covered a neighbor’s route. Every visit helped the team keep a clearer picture of the cats in our care.', '2026-11-01', 1, 2);
